import SkeletonService from '../../../../../src/services/SkeletonService';
import { getCollection } from '../../../../../src/lib/mongodb';

/**
 * TableCtrl - Laravel TableCtrl.php equivalent
 * Handles AJAX table data requests
 * Auto-generated by ModuleGenerator
 */
export default class TableCtrl {
  /**
   * index method - Main handler
   * @param {Request} req 
   * @param {Response} res 
   * @returns {Promise<Response>}
   */
  async index(req, res) {
    try {
      console.log('🎯 TableCtrl::index() called');

      // Extract and validate token from params (set by SystemRouteController)
      const token = req.params?.token || req.body?.skeleton_token;
      
      if (!token) {
        console.warn('⚠️ TableCtrl: No token provided');
        return res.status(400).json({
      status: false,
          title: 'Token Missing',
          message: 'No token was provided.'
        });
      }

      console.log(`📋 Resolving token: ${token}`);

      // Resolve token configuration
      const reqSet = await SkeletonService.resolveToken(token);

      if (!reqSet || !reqSet.status || !reqSet.key || !reqSet.table) {
        console.error('❌ TableCtrl: Invalid token configuration', reqSet);
        return res.status(400).json({
          status: false,
          title: 'Invalid Token',
          message: 'The provided token is invalid or lacks required configuration.'
        });
  }

      console.log('✅ Token resolved:', { key: reqSet.key, table: reqSet.table });

      // Set view to table and parse filters
      const draw = parseInt(req.body.draw || 1);
      const filters = req.body.skeleton_filters || {};

      // Handle different configuration keys
      switch (reqSet.key) {
        case 'central_automations_domain_jobs': {
          const jobsCollection = await getCollection('domain_enrichment_jobs', 'automation');
          const resultsCollection = await getCollection('domain_enrichment_results', 'automation');

          const page = parseInt(filters.pagination?.page || 1, 10);
          const limit = parseInt(filters.pagination?.limit || 25, 10);
          const skip = (page - 1) * limit;

          const search = (filters.search || '').trim();
          const statusFilter = filters.columns?.status?.search?.value || [];

          const query = {};

          if (search) {
            query.domain = { $regex: search, $options: 'i' };
          }

          if (Array.isArray(statusFilter) && statusFilter.length > 0) {
            query.status = { $in: statusFilter };
          }

          const recordsTotal = await jobsCollection.countDocuments({});
          const recordsFiltered = await jobsCollection.countDocuments(query);

          const pipeline = [
            { $match: query },
            { $sort: { created_at: -1 } },
            { $skip: skip },
            { $limit: limit },
            {
              $lookup: {
                from: 'domain_enrichment_results',
                localField: 'job_id',
                foreignField: 'job_id',
                as: 'result',
              },
            },
            {
              $addFields: {
                result: { $arrayElemAt: ['$result', 0] },
              },
            },
            {
              $project: {
                _id: 0,
                job_id: 1,
                batch_id: 1,
                domain: 1,
                status: 1,
                attempts: 1,
                error: 1,
                created_at: 1,
                updated_at: 1,
                company_name: '$result.company_name',
                address: '$result.address',
                phone: '$result.phone',
                score: '$result.score',
              },
            },
          ];

          const data = await jobsCollection.aggregate(pipeline).toArray();

          return res.status(200).json({
            status: true,
            draw,
            data,
            recordsTotal,
            recordsFiltered,
            title: 'Domain Enrichment Jobs',
            message: 'Jobs retrieved successfully',
          });
        }

        default:
          return res.status(400).json({
            status: false,
            title: 'Invalid Configuration',
            message: 'The configuration key is not supported.',
          });
      }

  } catch (error) {
      console.error('❌ TableCtrl error:', error);
    return res.status(500).json({
      status: false,
        title: 'Error',
        message: error.message || 'An error occurred while processing the request.'
    });
    }
  }
}
